import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();

  // --- PALETTE & TOKENS ---
  const colors = {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // --- STAGE BACKDROP (avoid void) ---
  const bgGeo = new THREE.PlaneGeometry(7, 6);
  const bgMat = new MeshBasicNodeMaterial();
  const vUv = uv();
  const topColor = vec3(new THREE.Color(colors.ink));
  const bottomColor = vec3(new THREE.Color(colors.surface));
  bgMat.colorNode = mix(bottomColor, topColor, vUv.y);

  const backdrop = new THREE.Mesh(bgGeo, bgMat);
  backdrop.position.z = -1.5;
  group.add(backdrop);

  // --- CONTACT SHADOW ---
  const shadowGeo = new THREE.PlaneGeometry(2.5, 1.2);
  const shadowMat = new MeshBasicNodeMaterial({
    color: 0x000000,
    transparent: true,
    opacity: 0.5,
    depthWrite: false
  });
  const shadow = new THREE.Mesh(shadowGeo, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(0, -1.1, -0.4);
  group.add(shadow);

  // --- MACHINED METAL BASE CARD ---
  const cardGeo = new THREE.BoxGeometry(2.2, 1.6, 0.1);
  const cardMat = new MeshStandardNodeMaterial({
    color: new THREE.Color(colors.surface),
    metalness: 0.55,
    roughness: 0.52,
    clearcoat: 0.2,
    clearcoatRoughness: 0.3
  });
  const card = new THREE.Mesh(cardGeo, cardMat);
  card.position.set(0, 0, 0);
  group.add(card);

  // Accent Chamfer Rim
  const rimGeo = new THREE.BoxGeometry(2.24, 1.64, 0.02);
  const rimMat = new MeshStandardNodeMaterial({
    color: new THREE.Color(colors.accent),
    emissive: new THREE.Color(colors.accent),
    emissiveIntensity: 1.2,
    metalness: 0.8,
    roughness: 0.2
  });
  const rim = new THREE.Mesh(rimGeo, rimMat);
  rim.position.set(0, 0, -0.05);
  group.add(rim);

  // --- LIGHTING ---
  const localKeyLight = new THREE.DirectionalLight('#ffffff', 1.2);
  localKeyLight.position.set(2, 3, 2);
  group.add(localKeyLight);

  const localRimLight = new THREE.DirectionalLight(colors.accent, 1.4);
  localRimLight.position.set(-2, -2, -1);
  group.add(localRimLight);

  // --- GLB ASSET (Gear Mesh) ---
  let gearMesh = null;
  const gearPivot = new THREE.Group();
  gearPivot.position.set(0.6, 0.2, 0.15);
  gearPivot.scale.setScalar(0.7);
  group.add(gearPivot);

  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      const model = gltf.scene;

      // Override materials to match machined-metal aesthetic
      model.traverse((child) => {
        if (child.isMesh) {
          child.material = new MeshStandardNodeMaterial({
            color: new THREE.Color(colors.paper),
            metalness: 0.55,
            roughness: 0.45,
            clearcoat: 0.25
          });
        }
      });

      gearPivot.add(model);
      gearMesh = model;
    }).catch(err => {
      console.warn("Failed to load gear GLB, rendering fallback indicator.", err);
      // Fallback fallback shape
      const fallbackGeo = new THREE.TorusGeometry(0.3, 0.08, 12, 24);
      const fallbackMesh = new THREE.Mesh(fallbackGeo, cardMat);
      gearPivot.add(fallbackMesh);
      gearMesh = fallbackMesh;
    });
  }

  // --- TYPOGRAPHY / LABELS ---
  // Large Stat Metric Value (Lora Serif)
  const valText = ctx.fontAtlas.createText('28', {
    fontSize: 0.46,
    color: colors.paper,
    align: 'left'
  });
  valText.position.set(-0.8, 0.1, 0.08);
  group.add(valText);

  // Stat Label (JetBrains Mono)
  const labelText = ctx.fontAtlas.createText('ENGINEERED COMP.', {
    fontSize: 0.09,
    color: colors.accent,
    align: 'left',
    letterSpacingPx: 1.5
  });
  labelText.position.set(-0.8, -0.3, 0.08);
  group.add(labelText);

  // Small auxiliary detail
  const detailText = ctx.fontAtlas.createText('CAL. NA-01 / ATELIER', {
    fontSize: 0.06,
    color: '#8b8b94',
    align: 'left'
  });
  detailText.position.set(-0.8, -0.5, 0.08);
  group.add(detailText);

  // --- AMBIENT IDLE ROTATION ---
  const clock = new THREE.Clock();
  let animId = null;

  function update() {
    animId = requestAnimationFrame(update);
    const elapsed = clock.getElapsedTime();
    if (gearMesh) {
      gearMesh.rotation.z = elapsed * 0.2;
    }
  }
  update();

  // --- SYSTEM PRIMITIVE PIPELINE ---
  const activePrimitives = [];
  if (config.cinematicPrimitives) {
    config.cinematicPrimitives.forEach((prim) => {
      if (ctx.primitives[prim.name]) {
        const handler = ctx.primitives[prim.name](group, prim.params);
        if (handler) activePrimitives.push(handler);
      }
    });
  }

  // --- INTERACTIVITY & HANDLERS ---
  let hoverTl = null;

  group.userData.handlers = {
    pointerover: () => {
      if (hoverTl) hoverTl.kill();
      hoverTl = gsap.timeline();
      // "rise-in (subtle, 0.15 scene units)"
      hoverTl.to(card.position, { z: 0.15, duration: 0.4, ease: 'power2.out' });
      hoverTl.to(rim.position, { z: 0.10, duration: 0.4, ease: 'power2.out' }, 0);
      hoverTl.to(valText.position, { z: 0.23, duration: 0.4, ease: 'power2.out' }, 0);
      hoverTl.to(labelText.position, { z: 0.23, duration: 0.4, ease: 'power2.out' }, 0);
      hoverTl.to(detailText.position, { z: 0.23, duration: 0.4, ease: 'power2.out' }, 0);
      if (gearPivot) {
        hoverTl.to(gearPivot.position, { z: 0.3, duration: 0.4, ease: 'power2.out' }, 0);
      }
    },
    pointerout: () => {
      if (hoverTl) hoverTl.kill();
      hoverTl = gsap.timeline();
      hoverTl.to(card.position, { z: 0, duration: 0.5, ease: 'power3.out' });
      hoverTl.to(rim.position, { z: -0.05, duration: 0.5, ease: 'power3.out' }, 0);
      hoverTl.to(valText.position, { z: 0.08, duration: 0.5, ease: 'power3.out' }, 0);
      hoverTl.to(labelText.position, { z: 0.08, duration: 0.5, ease: 'power3.out' }, 0);
      hoverTl.to(detailText.position, { z: 0.08, duration: 0.5, ease: 'power3.out' }, 0);
      if (gearPivot) {
        hoverTl.to(gearPivot.position, { z: 0.15, duration: 0.5, ease: 'power3.out' }, 0);
      }
    },
    click: () => {
      // Scale dynamic press response
      const pressTl = gsap.timeline();
      pressTl.to(group.scale, { x: 0.95, y: 0.95, z: 0.95, duration: 0.1, ease: 'power2.out' });
      pressTl.to(group.scale, { x: 1, y: 1, z: 1, duration: 0.3, ease: 'back.out(1.8)' });

      // Emit selection action
      ctx.emit('hub-collection.select', { value: 28 });
    }
  };

  // --- CLEANUP ---
  group.userData.cleanup = () => {
    cancelAnimationFrame(animId);
    if (hoverTl) hoverTl.kill();
    activePrimitives.forEach((p) => {
      if (p.cleanup) p.cleanup();
    });
    // Traverse & dispose geometries/materials local to card
    cardGeo.dispose();
    cardMat.dispose();
    rimGeo.dispose();
    rimMat.dispose();
    bgGeo.dispose();
    bgMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();
  };

  // Apply visual speculative scale and adjustments
  group.position.set(0, -0.2, 0);

  return group;
}
